const site=document.querySelector('#site'),app=document.querySelector('#app'),content=document.querySelector('#content'),dialog=document.querySelector('#agent-dialog');let token=sessionStorage.getItem('auven-admin-token')||'',current='overview';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options={}){const r=await fetch('/api'+path,{...options,headers:{'content-type':'application/json',...(token?{authorization:'Bearer '+token}:{}),...options.headers}});let data=await r.json();if(!r.ok)throw Error(data.error||'request_failed');return data}
function openApp(){site.hidden=true;app.hidden=false;window.scrollTo(0,0);render('overview')}function home(e){e.preventDefault();app.hidden=true;site.hidden=false;window.scrollTo(0,0)}document.querySelectorAll('[data-app]').forEach(b=>b.onclick=openApp);document.querySelectorAll('[data-home]').forEach(b=>b.onclick=home);document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>render(b.dataset.page));document.querySelectorAll('.close').forEach(b=>b.onclick=()=>dialog.close());
const filters={activity:'all',proofs:'all'};
const contextSidebar=document.querySelector('#context-sidebar'),appBody=document.querySelector('#app-body');
function syncContext(page){
  const sections={
    activity:{title:'ACTIVITY',items:[['all','All events'],['allowed','Allowed'],['denied','Denied'],['failed','Failed']]},
    proofs:{title:'PROOFS',items:[['all','All proofs'],['submitted','Submitted'],['local','Not submitted']]}
  };
  const section=token?sections[page]:null;
  contextSidebar.hidden=!section;
  appBody.classList.toggle('has-context',!!section);
  if(section){
    contextSidebar.innerHTML='<div class="context-title">'+section.title+'</div><nav>'+section.items.map(([value,label])=>'<button type="button" data-context="'+value+'" class="'+(filters[page]===value?'active':'')+'">'+label+'</button>').join('')+'</nav>';
    contextSidebar.querySelectorAll('[data-context]').forEach(button=>button.onclick=()=>{filters[page]=button.dataset.context;render(page)});
  }else contextSidebar.innerHTML='';
  document.querySelectorAll('.app-tabs [data-page]').forEach(button=>button.setAttribute('aria-current',button.dataset.page===page?'page':'false'));
}
const button='<button class="button dark" data-create>+ Connect agent</button>';const empty=(title,copy)=>`<div class="empty"><div class="empty-icon">◈</div><h3>${title}</h3><p>${copy}</p></div>`;
async function render(page){current=page;syncContext(page);document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(!token){content.innerHTML=`<div class="page-top"><div><h1>Open your workspace</h1><p>Use a workspace token to manage connected agents.</p></div></div><section class="panel" style="padding:24px;max-width:500px"><form id="setup"><label>Workspace name<input name="name" placeholder="My team"></label><label>Existing admin token<input name="token" placeholder="Paste a token to sign in"></label><label>Setup token (if required)<input name="setup" placeholder="Optional"></label><p class="subtle">Create a workspace or paste your existing token. Admin tokens are kept for this browser session only.</p><button class="button dark" style="margin-top:20px">Continue</button><p id="setup-error" class="subtle"></p></form></section>`;document.querySelector('#setup').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{if(f.get('token'))token=String(f.get('token')).trim();else{let x=await api('/workspaces',{method:'POST',headers:{'x-setup-token':String(f.get('setup'))},body:JSON.stringify({name:f.get('name')})});token=x.admin_token;alert('Save your workspace admin token now. It will not be shown again:\n\n'+token)}sessionStorage.setItem('auven-admin-token',token);await render(page)}catch(err){token='';sessionStorage.removeItem('auven-admin-token');document.querySelector('#setup-error').textContent=err.message}};return}
try{let agents=(await api('/agents')).agents;let events=page==='overview'||page==='activity'?(await api('/events')).events:[];const rows=agents.map(a=>`<div class="agent-row"><div class="mini-icon violet">◈</div><div><strong>${esc(a.name)}</strong><small>${esc(a.purpose)} · $${(a.daily_limit/100).toFixed(2)} / day</small></div><span class="pill">${esc(a.status)}</span><button class="delete" data-status="${esc(a.id)}" data-next="${a.status==='active'?'stopped':'active'}">${a.status==='active'?'Stop':'Resume'}</button></div>`).join('');
const top=(title,copy,action='')=>`<div class="page-top"><div><h1>${title}</h1><p>${copy}</p></div>${action}</div>`;
if(page==='overview')content.innerHTML=top('Welcome to AUVEN','Manage external agents through the gateway.',button)+`<div class="notice">Gateway policies apply to supported requests sent through AUVEN. Mainnet publishing requires a configured server signer.</div><div class="stats"><div class="stat"><span>Connected agents</span><strong>${agents.length}</strong></div><div class="stat"><span>Gateway events</span><strong>${events.length}</strong></div><div class="stat"><span>Network</span><strong style="font-size:17px">Mainnet</strong><small>Robinhood Chain · 4663</small></div></div><section class="panel wide-panel"><div class="panel-head"><h2>Agents</h2></div>${rows||empty('No agents registered','Connect an external agent to start.')}</section>`;
else if(page==='agents')content.innerHTML=top('Agents','Register agents running in your own applications.',button)+`<section class="panel"><div class="panel-head"><h2>Registered agents</h2></div>${rows||empty('No agents registered','Create an identity and gateway credential for your first agent.')}</section>`;
else if(page==='activity')content.innerHTML=top('Activity','Gateway requests and policy decisions.')+`<section class="panel">${events.filter(e=>filters.activity==='all'||e.decision===filters.activity).map(e=>`<div class="agent-row"><div><strong>${esc(e.decision)} · ${esc(e.reason)}</strong><small>${esc(e.agent_id)} · ${esc(e.created_at)} · reserved $${(e.reserved/100).toFixed(2)}</small></div></div>`).join('')||empty(filters.activity==='all'?'No activity yet':'No matching events',filters.activity==='all'?'Gateway requests will appear here.':'Try another activity filter.')}</section>`;
else if(page==='proofs'){const proofs=(await api('/proofs')).proofs;content.innerHTML=top('Proofs','ML-DSA-65 signed passports and checkpoints.')+`<div class="notice">Publishing writes the hash of a signed proof to Robinhood Chain mainnet and spends gas. A proof is confirmed only after its transaction is verified.</div><section class="panel">${proofs.filter(x=>filters.proofs==='all'||(filters.proofs==='submitted'?!!x.tx_hash:!x.tx_hash)).map(x=>`<div class="agent-row"><div><strong>${esc(x.kind)} · ${esc(x.agent_id)}</strong><small>${esc(x.created_at)} · ${esc(x.chain_status||'not published')}</small>${x.tx_hash?`<small><a target="_blank" rel="noreferrer" href="https://robinhoodchain.blockscout.com/tx/${esc(x.tx_hash)}">View transaction ↗</a></small>`:''}</div><button class="button outline" data-download="${esc(x.id)}">Export</button>${x.tx_hash?`<button class="button outline" data-check="${esc(x.id)}">Verify</button>`:!x.chain_status?`<button class="button dark" data-publish="${esc(x.id)}">Publish</button>`:''}</div>`).join('')||empty(filters.proofs==='all'?'No proofs yet':'No matching proofs',filters.proofs==='all'?'Passports appear after registration.':'Try another proof filter.')}</section>`;content.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>{const p=proofs.find(x=>x.id===b.dataset.download);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(p.payload,null,2)],{type:'application/json'}));a.download=`auven-proof-${p.id}.json`;a.click();URL.revokeObjectURL(a.href)});content.querySelectorAll('[data-publish]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/proofs/'+b.dataset.publish+'/publish',{method:'POST'});render('proofs')}catch(e){alert(e.message);render('proofs')}});content.querySelectorAll('[data-check]').forEach(b=>b.onclick=async()=>{try{const x=await api('/proofs/'+b.dataset.check+'/inclusion');alert(x.included?'Confirmed on Robinhood Chain mainnet':'Not confirmed: '+x.reason);render('proofs')}catch(e){alert(e.message)}})}
else if(page==='policies')content.innerHTML=top('Policies','Deterministic gateway controls.')+`<section class="panel" style="padding:24px"><h2>Current policy</h2><p class="subtle">Only registered, active agents with sufficient daily budget can call the configured OpenAI provider. Every request needs an idempotency key. Stop an agent from the Agents page to revoke gateway access.</p></section>`;
else content.innerHTML=top('Settings','Workspace access and network configuration.')+`<section class="panel" style="padding:24px"><h2>Session</h2><p class="subtle">Your admin token is stored only for this browser session.</p><button class="button outline" id="signout">Sign out</button></section>`;
content.querySelectorAll('[data-create]').forEach(b=>b.onclick=()=>dialog.showModal());content.querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{await api('/agents/'+b.dataset.status+'/status',{method:'PATCH',body:JSON.stringify({status:b.dataset.next})});render(page)});if(document.querySelector('#signout'))document.querySelector('#signout').onclick=()=>{token='';sessionStorage.removeItem('auven-admin-token');render('overview')};
}catch(err){token='';sessionStorage.removeItem('auven-admin-token');render(page)}}
document.querySelector('#agent-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const x=await api('/agents',{method:'POST',body:JSON.stringify({name:f.get('name'),purpose:f.get('purpose'),daily_limit_cents:Math.round(Number(f.get('budget'))*100)})});dialog.close();e.target.reset();alert('Save this agent credential now. It will not be shown again:\n\n'+x.agent.credential);render('agents')}catch(err){alert(err.message)}};
